import React, { useState, useMemo } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { User, UserRole, UserStatus } from '../types';
import { User as UserIcon, Edit2, Activity, UserPlus, Calendar, Shield, Briefcase, Mail, Power, ShieldCheck, Database, Key, Hash, MapPin, ShieldAlert } from 'lucide-react';
import { NewUserModal } from './NewUserModal';

const ResizeHandle = ({ onResize }: { onResize: (delta: number) => void }) => {
  const handleMouseDown = (e: React.MouseEvent) => {
    e.preventDefault();
    const startX = e.pageX;
    const handleMouseMove = (moveEvent: MouseEvent) => {
      onResize(moveEvent.pageX - startX);
    };
    const handleMouseUp = () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div 
      onMouseDown={handleMouseDown}
      className="absolute right-0 top-0 bottom-0 w-1.5 cursor-col-resize hover:bg-indigo-500/30 active:bg-indigo-600/50 transition-colors z-30 group-hover:bg-slate-200/50"
    />
  );
};

