        [UserRole.HEAD]: users.filter(u => u.role === UserRole.HEAD).length,
        [UserRole.ANALYST]: users.filter(u => u.role === UserRole.ANALYST).length,
    };
    return { total, active, inactive, roles };
  }, [users]);

