    setSelectedUser(user);
    setIsModalOpen(true);
  };

  const handleNewUserClick = () => {
    setSelectedUser(null);
    setIsModalOpen(true);
  };

  return (
    <div className="flex-1 overflow-y-auto custom-scrollbar p-8 space-y-8 bg-[#F8FAFC]">
        <div className="flex flex-col md:flex-row gap-6">
