                        <Activity size={20} strokeWidth={2.5}/>
                    </div>
                    <div>
                        <p className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Activos</p>
                        <p className="text-2xl font-black text-slate-900 tracking-tighter">{stats.active}</p>
