  // Col Widths for List View
  const [colWidths, setColWidths] = useState<number[]>(() => {
    const saved = localStorage.getItem(STORAGE_KEY_COLS);
    return saved ? JSON.parse(saved) : [80, 450, 120, 120, 140, 140, 100, 60];
  });

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY_COLS, JSON.stringify(colWidths));
  }, [colWidths]);

  const handleResize = (index: number, delta: number) => {
    setColWidths(prev => {
      const newWidths = [...prev];
      newWidths[index] = Math.max(50, prev[index] + delta);
      return newWidths;
    });
