    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');
    const req = requests.find(r => r.id === requestId);
    if (!req || req.status === targetStatus) return;
    try {
        await updateStatus(requestId, targetStatus);
